import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        StringTokenizer st = new StringTokenizer("");
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tokens.add(st.nextToken());
        }
        int n = Integer.parseInt(tokens.get(0));
        String[] a = tokens.subList(1, 1 + n).toArray(new String[0]);
        int[] resolved = new int[n], path = new int[n];
        Arrays.fill(resolved, -1);
        for (int i = 0; i < n; i++) {
            int len = 0, v = i;
            // follow references until a resolved entry, then fill the whole path
            while (resolved[v] < 0) {
                path[len++] = v;
                if (a[v].charAt(0) != '!') { resolved[v] = a[v].charAt(a[v].length() - 1) - '1'; break; }
                v = Integer.parseInt(a[v].substring(1)) - 1;
            }
            for (int k = 0; k < len; k++) resolved[path[k]] = resolved[v];
        }
        long[] counts = new long[3];
        for (int r : resolved) counts[r]++;
        System.out.println(counts[0] + " " + counts[1] + " " + counts[2]);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	var n int
	fmt.Fscan(in, &n)
	a := make([]string, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	resolved := make([]int, n)
	for i := range resolved {
		resolved[i] = -1
	}
	var path []int
	for i := 0; i < n; i++ {
		path = path[:0]
		v := i
		// follow references until a resolved entry, then fill the whole path
		for resolved[v] < 0 {
			path = append(path, v)
			if a[v][0] != '!' {
				resolved[v] = int(a[v][len(a[v])-1] - '1')
				break
			}
			j, _ := strconv.Atoi(a[v][1:])
			v = j - 1
		}
		for _, w := range path {
			resolved[w] = resolved[v]
		}
	}
	var counts [3]int
	for _, r := range resolved {
		counts[r]++
	}
	fmt.Println(counts[0], counts[1], counts[2])
}
